WITH kept_keys AS (SELECT product_id, id FROM order_items EXCEPT ALL SELECT product_id, id FROM order_items WHERE product_id IS NULL), reconciled AS (SELECT s.* FROM order_items s JOIN kept_keys k ON s.product_id = k.product_id AND s.id = k.id) SELECT order_id, BIT_AND(quantity) AS quantity_bit_and, COUNT(DISTINCT order_id) AS distinct_order_ids, CORR(quantity, unit_price) AS corr_quantity_unit_price FROM reconciled GROUP BY order_id HAVING distinct_order_ids > 1 ORDER BY order_id DESC NULLS FIRST
